import{_ as t,c as n,o as a,a2 as s}from"./chunks/framework.PGES7OoM.js";const p=JSON.parse('{"title":"Send assets privately","description":"","frontmatter":{"rawMarkdown":"# Send assets privately\\n\\nOpen **Send** in the Curvy App. At the top of the form you pick the recipient type, depending on whether the recipient:\\n\\n- already has a registered Curvy ID: [Curvy ID](#send-to-curvy-id)\\n- wants to receive funds to a regular blockchain account (EOA address): [External wallet](#send-to-external-wallet)\\n- doesn\'t have a crypto wallet or address but wants to onboard to Curvy: [Gift link](#send-a-gift-link)\\n\\nIn all three cases you choose the asset and amount, then **Review transfer** shows the full details, including fees, before you confirm.\\nAfter confirming you can follow the transfer as it is prepared, submitted, and settled, and find it again later under **Activity**.\\n\\n## Send to Curvy ID\\n\\nWhen the recipient already has a registered Curvy ID, select **Curvy ID** and type their name, for example `mihailo.curvy.name`.\\nThey don\'t have to be a saved contact, although you can save them as one for next time.\\n\\nThis is a fully private transfer: nothing about the sender, the recipient, or the amount is visible on-chain.\\n\\n## Send to external wallet\\n\\nWhen the recipient only has a blockchain address they can share with you, select **External wallet**. You\'ll need to select\\nboth the network where they will receive the funds and the exact address, for example `0xd8d...` on Polygon or a Solana address.\\n\\n> [!WARNING]\\n> This is a withdrawal from your private balance. The amount, destination address, and timing are visible on the destination network.\\n\\n## Send a gift link\\n\\nThe third option, **Gift link**, allows you to generate a single-use link that\\nanyone can use to register or log in to a Curvy account and claim the funds you\'ve sent them.\\n\\nThis is useful in situations where:\\n\\n- You have a secure messaging channel with the recipient but don\'t know their address or Curvy name\\n- The user doesn\'t have Curvy or any other crypto wallet\\n- You want to give someone a crypto \\"giftcard\\"\\n\\n> [!WARNING]\\n> A couple of important things about the **Gift link** feature:\\n> <br>\\n>\\n> 1. Curvy links don\'t expire! The only way for you to get back the funds that were unclaimed is to claim the funds using the link yourself.\\n> <br>\\n> 2. Make sure that you always back up the link before sending!\\n> <br>\\n> 3. Keep the links safe, as anyone who gains access to them will also gain access to the funds they are sending!\\n> <br>\\n\\nAfter you enter the amount and asset, **Review gift** repeats these warnings and shows the fees. Once you confirm, wait for the private transfer to finish.\\n\\nThe transfer view then shows the gift link, with a copy button and a QR code. Save it somewhere safe before you share it:\\nyou can reopen it from the transfer view during this session, but not from another device.\\n\\nYour recipient opens a link of the form\\n\\n```\\nhttps://app.curvy.box/claim/<gift-id>\\n```\\n\\nlogs in to, or registers, any Curvy ID, reviews the gift and chooses **Claim gift**.\\nA small claim fee is deducted from the gift amount, and the link stops working once claimed.\\n","rawMarkdownPath":"/_raw/for-users/send-assets-privately.md","rawMarkdownTitle":"Send assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/send-assets-privately.md"},"headers":[],"relativePath":"for-users/send-assets-privately.md","filePath":"for-users/send-assets-privately.md","lastUpdated":1791449043000}'),o={name:"for-users/send-assets-privately.md"};function r(i,e,l,h,d,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="send-assets-privately" tabindex="-1">Send assets privately <a class="header-anchor" href="#send-assets-privately" aria-label="Permalink to &quot;Send assets privately&quot;">​</a></h1><p>Open <strong>Send</strong> in the Curvy App. At the top of the form you pick the recipient type, depending on whether the recipient:</p><ul><li>already has a registered Curvy ID: <a href="#send-to-curvy-id">Curvy ID</a></li><li>wants to receive funds to a regular blockchain account (EOA address): <a href="#send-to-external-wallet">External wallet</a></li><li>doesn&#39;t have a crypto wallet or address but wants to onboard to Curvy: <a href="#send-a-gift-link">Gift link</a></li></ul><p>In all three cases you choose the asset and amount, then <strong>Review transfer</strong> shows the full details, including fees, before you confirm. After confirming you can follow the transfer as it is prepared, submitted, and settled, and find it again later under <strong>Activity</strong>.</p><h2 id="send-to-curvy-id" tabindex="-1">Send to Curvy ID <a class="header-anchor" href="#send-to-curvy-id" aria-label="Permalink to &quot;Send to Curvy ID&quot;">​</a></h2><p>When the recipient already has a registered Curvy ID, select <strong>Curvy ID</strong> and type their name, for example <code>mihailo.curvy.name</code>. They don&#39;t have to be a saved contact, although you can save them as one for next time.</p><p>This is a fully private transfer: nothing about the sender, the recipient, or the amount is visible on-chain.</p><h2 id="send-to-external-wallet" tabindex="-1">Send to external wallet <a class="header-anchor" href="#send-to-external-wallet" aria-label="Permalink to &quot;Send to external wallet&quot;">​</a></h2><p>When the recipient only has a blockchain address they can share with you, select <strong>External wallet</strong>. You&#39;ll need to select both the network where they will receive the funds and the exact address, for example <code>0xd8d...</code> on Polygon or a Solana address.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>This is a withdrawal from your private balance. The amount, destination address, and timing are visible on the destination network.</p></div><h2 id="send-a-gift-link" tabindex="-1">Send a gift link <a class="header-anchor" href="#send-a-gift-link" aria-label="Permalink to &quot;Send a gift link&quot;">​</a></h2><p>The third option, <strong>Gift link</strong>, allows you to generate a single-use link that anyone can use to register or log in to a Curvy account and claim the funds you&#39;ve sent them.</p><p>This is useful in situations where:</p><ul><li>You have a secure messaging channel with the recipient but don&#39;t know their address or Curvy name</li><li>The user doesn&#39;t have Curvy or any other crypto wallet</li><li>You want to give someone a crypto &quot;giftcard&quot;</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>A couple of important things about the <strong>Gift link</strong> feature: <br></p><ol><li>Curvy links don&#39;t expire! The only way for you to get back the funds that were unclaimed is to claim the funds using the link yourself. <br></li><li>Make sure that you always back up the link before sending! <br></li><li>Keep the links safe, as anyone who gains access to them will also gain access to the funds they are sending! <br></li></ol></div><p>After you enter the amount and asset, <strong>Review gift</strong> repeats these warnings and shows the fees. Once you confirm, wait for the private transfer to finish.</p><p>The transfer view then shows the gift link, with a copy button and a QR code. Save it somewhere safe before you share it: you can reopen it from the transfer view during this session, but not from another device.</p><p>Your recipient opens a link of the form</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.curvy.box/claim/&lt;gift-id&gt;</span></span></code></pre></div><p>logs in to, or registers, any Curvy ID, reviews the gift and chooses <strong>Claim gift</strong>. A small claim fee is deducted from the gift amount, and the link stops working once claimed.</p>',20)])])}const f=t(o,[["render",r]]);export{p as __pageData,f as default};
